INSERT INTO public.app_releases (version, title, summary, details, category) VALUES
('1.1.0', 'Ticket médio corrigido e auto-update do desktop', 'Correção do cálculo do ticket médio (vendas em Nota não puxam mais o valor para baixo) e do fluxo de atualização automática do aplicativo instalado no PC.', 'Cálculo do ticket médio no Dashboard e no Assistente passou a usar o valor total das vendas dividido pela quantidade — vendas fiadas (Nota) não distorcem mais o indicador. O aplicativo desktop agora publica releases e arquivos de metadados (latest.yml) via GitHub Releases, então "Verificar atualizações" na bandeja realmente baixa e instala versões novas, com notificações mostrando o progresso.', 'bugfix');